"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3161],{7858(e){e.exports=JSON.parse('{"title":"\ubaa8\ub2c8\ud130\ub9c1 \ub3c4\uad6c \ucc98\uc74c\ubd80\ud130 \uad6c\ud604\ud558\uae30","date":"2025-03-20","coverUrl":"/kudzu-based-bench/assets/notion/45f7786988b8950e.png","html":"<h2 data-notion-block-id=\\"1bbe548d-8a8e-801b-b75a-d0dd4e1d210e\\" id=\\"1bbe548d-8a8e-801b-b75a-d0dd4e1d210e\\">\ubaa8\ub2c8\ud130\ub9c1 \ub3c4\uad6c \ucc98\uc74c\ubd80\ud130 \uad6c\ud604\ud558\uae30</h2><a href=\\"https://programmingarehard.com/2025/03/11/react-router-error-reporting.html/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://programmingarehard.com/2025/03/11/react-router-error-reporting.html/</a><p data-notion-block-id=\\"1bbe548d-8a8e-806a-a531-ff95f81acbb1\\">\uc5d0\ub7ec\ub97c \ud0d0\uc9c0\uc704\ud574 Sentry\ub098 datadog\uac19\uc740 \ubaa8\ub2c8\ud130\ub9c1 \ud234\uc744 \uc0ac\uc6a9\ud560 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc0ac\uc6a9\ud558\uae30 \ud798\ub4e4 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 React Router\uc758 production\uc5d0\uc11c \uc5d0\ub7ec\ub97c \ubaa8\ub2c8\ud130\ub9c1\ud558\uae30 \uc704\ud574 Source map \ub9e4\ud551, \ucee4\uc2a4\ud140 \uc11c\ubc84 \uad6c\ud604\ud558\ub294 \uacfc\uc815\uae4c\uc9c0 \uad6c\ud604\ud558\ub294 \uacfc\uc815\uc744 \ub2f4\uc740 \uae00\uc785\ub2c8\ub2e4. analytics \ub3c4\uad6c\ub098 \uc5ec\ub7ec \ub3c4\uad6c\uc640 \uc5f0\uacb0\ud558\uba74 \uc88b\uc740 \ubaa8\ub2c8\ud130\ub9c1 \ud234\uc744 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\uc744 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"1bbe548d-8a8e-804b-b128-e8f07fbf0478\\" id=\\"1bbe548d-8a8e-804b-b128-e8f07fbf0478\\">React Router\uc758 \ubaa8\ub4c8 \ucd5c\uc801\ud654</h2><a href=\\"https://remix.run/blog/split-route-modules\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/split-route-modules</a><p data-notion-block-id=\\"1bbe548d-8a8e-80a6-bae0-c3ef8b29aaa1\\">React Router\uc5d0\uc11c \ub80c\ub354\ub9c1\ud558\ub294 \uacfc\uc815\uc744 \ube60\ub974\uac8c \ud558\uae30 \uc704\ud574\uc11c \ub77c\uc6b0\ud130 \ubaa8\ub4c8\uc744 \ub3d9\uc2dc\uc5d0 \ub2e4\uc6b4\ubc1b\ub294 \uae30\ub2a5\uc744 \ucd9c\uc2dc\ud588\uc2b5\ub2c8\ub2e4. \uc81c\ud55c\uc0ac\ud56d\uc774 \uc788\uace0 \uc2e4\ud5d8 \uae30\ub2a5\uc774\uc9c0\ub9cc, \ubaa8\ub4c8\uc758 \uc0ac\uc774\uc988\uac00 \ucee4\uc9c0\ub294 \uacbd\uc6b0\uc5d0 \uc88b\uc740 \uae30\ub2a5\uc774 \ub420 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"1bce548d-8a8e-800f-8706-c3ff276b0f6e\\" id=\\"1bce548d-8a8e-800f-8706-c3ff276b0f6e\\">React Native Renaimated \ub4e4\uc5ec\ub2e4\ubcf4\uae30</h2><a href=\\"https://blog.swmansion.com/how-react-native-reanimated-updates-the-styles-a-deep-dive-338ab22e9f21\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.swmansion.com/how-react-native-reanimated-updates-the-styles-a-deep-dive-338ab22e9f21</a><p data-notion-block-id=\\"1bce548d-8a8e-8085-b693-e5aaef907946\\">React Native Renaimated\uac00 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \uc804\ub2ec\ud558\ub294 props\ub97c \ubd84\ub9ac\ud574\uc11c \uc804\ub2ec\ud558\uc5ec \uc2a4\ud0c0\uc77c \uc5c5\ub370\uc774\ud2b8\ub97c \ucd5c\uc801\ud654\ud55c\ub2e4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b8e548d-8a8e-80b4-9391-f95abdb6e7a4\\" id=\\"1b8e548d-8a8e-80b4-9391-f95abdb6e7a4\\">AV1\uc740 \ubb34\uc5c7\uc774\uace0 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud560\uae4c</h2><a href=\\"https://evilmartians.com/chronicles/better-web-video-with-av1-codec\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://evilmartians.com/chronicles/better-web-video-with-av1-codec</a><p data-notion-block-id=\\"1b6e548d-8a8e-8093-a138-e40d0e912e58\\">\ub3d9\uc601\uc0c1\uc744 \uc62c\ub9ac\uace0 \ubcf4\uc5ec\uc8fc\ub294 \uc0ac\uc774\ud2b8\ub97c \ub9cc\ub4e4\ub2e4\ubcf4\uba74 \ub3d9\uc601\uc0c1\uc758 \uc555\ucd95\ub960\uc5d0 \ub300\ud574 \uace0\ubbfc\uc744 \ub9ce\uc774\ud558\uac8c\ub429\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ucd5c\uc2e0 \ube0c\ub77c\uc6b0\uc800\ub97c \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc9c4 AV1 \ucf54\ub371\uc5d0 \ub300\ud574 \uc124\uba85\ud558\uace0 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. ffmpeg\uc5d0 \ub300\ud574 \uc124\uba85\ud558\ub294 \ubd80\ubd84\uc774 \ub354 \uae38\uc9c0\ub9cc, ffmpeg \uc0ac\uc6a9\uc5d0 \ub300\ud55c \uc124\uba85\uc774\ub098 AV1\uc5d0 \ub300\ud55c \uc124\uba85\uc740 \uc774\ud574\ud558\uae30 \uc27d\uac8c \ub418\uc5b4\uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b8e548d-8a8e-80df-8387-c29a1391a039\\" id=\\"1b8e548d-8a8e-80df-8387-c29a1391a039\\">Next.js\ub97c \uc0ac\uc6a9\ud558\uba74 \ud2b8\ub798\ud53d\uc744 \uc5bc\ub9c8\ub098 \uc904\uc77c \uc218 \uc788\uc744\uae4c</h2><a href=\\"https://martijnhols.nl/blog/how-much-traffic-can-a-pre-rendered-nextjs-site-handle\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://martijnhols.nl/blog/how-much-traffic-can-a-pre-rendered-nextjs-site-handle</a><p data-notion-block-id=\\"1b8e548d-8a8e-8086-8562-dc79728e360b\\">Next.js\uc758 prerender\ub97c \uc0ac\uc6a9\ud558\uba74 \uc5bc\ub9c8\ub098 \ud2b8\ub798\ud53d\uc744 \uc904\uc77c \uc218 \uc788\uc744\uc9c0\ub97c \uce21\uc815\ud55c \ud765\ubbf8\ub85c\uc6b4 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b8e548d-8a8e-80f7-bbf4-f6a29a7bf4fe\\" id=\\"1b8e548d-8a8e-80f7-bbf4-f6a29a7bf4fe\\">memoization\ub300\uc2e0 \ucef4\ud3ec\ub10c\ud2b8 \ubd84\ub9ac.</h2><a href=\\"https://cekrem.github.io/posts/beyond-react-memo-smarter-performance-optimization/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://cekrem.github.io/posts/beyond-react-memo-smarter-performance-optimization/</a><p data-notion-block-id=\\"1bbe548d-8a8e-806a-b9a5-f432278a5141\\">\uc0c1\ud0dc\ub97c \uc5ec\ub7ec\uad70\ub370\uc5d0\uc11c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74 \ucef4\ud3ec\ub10c\ud2b8 \ubd84\ub9ac\ub97c \ud1b5\ud574 memoization\uc73c\ub85c \ub9ac\ub80c\ub354\ub9c1\uc744 \ub9c9\ub294 \ub300\uc2e0 children\uc73c\ub85c \uc804\ub2ec\ud574 \ub9ac\ub80c\ub354\ub9c1\uc744 \ub9c9\ub294 \ubc29\uc2dd\uc744 \uad8c\uc7a5\ud55c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b6e548d-8a8e-80ca-b703-c01c2e2959e6\\" id=\\"1b6e548d-8a8e-80ca-b703-c01c2e2959e6\\">SVG\ub97c \ub354 \uac00\ub3c5\uc131\uc744 \uc88b\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4</h2><a href=\\"https://persevering.substack.com/p/super-crispy-svg-icons\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://persevering.substack.com/p/super-crispy-svg-icons</a><p data-notion-block-id=\\"1b8e548d-8a8e-80f5-bc56-e8ed00673d8d\\">\uc800\uc790\uac00 SVG \uc544\uc774\ucf58\uc744 \ub514\uc790\uc778 \ud560 \ub54c \uace0\ub824\ud558\ub294 \uac83\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. path\ub97c \ub2e8\ucd95\ud558\ub294 \uac83\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1a7e548d-8a8e-8020-8920-dd3de07abfef#1ade548d-8a8e-80f9-af85-e16f77252e47\\">SVG\ub97c \ud1b5\ud55c \uc560\ub2c8\uba54\uc774\uc158\uc744 \uad6c\ud604</a>\ud574\uc57c \ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \ud558\uc9c0 \ub9d0\uc544\uc57c \ud558\uc9c0\ub9cc, \uc88b\uc740 \ud301\ub4e4\uc774 \ub9ce\uc774 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b6e548d-8a8e-80f9-bfac-fa6ec4b6d3f5\\" id=\\"1b6e548d-8a8e-80f9-bfac-fa6ec4b6d3f5\\">Jotai\ub294 Weakmap\uc744 \uc0ac\uc6a9\ud55c\ub2e4</h2><a href=\\"https://newsletter.daishikato.com/p/how-the-jotai-store-api-is-inspired-by-the-weakmap-api\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://newsletter.daishikato.com/p/how-the-jotai-store-api-is-inspired-by-the-weakmap-api</a><p data-notion-block-id=\\"1b8e548d-8a8e-80e0-bf98-f15e529fb408\\">WeakMap\uc774 \ubb34\uc5c7\uc774\uace0, Jotai\uac00 \uc5b4\ub5bb\uac8c \uc601\ud5a5\uc744 \ubc1b\uc544\uc11c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b8e548d-8a8e-802b-9eed-f2563e85db0d\\" id=\\"1b8e548d-8a8e-802b-9eed-f2563e85db0d\\">WebGPU \ud29c\ud1a0\ub9ac\uc5bc</h2><a href=\\"https://okaydev.co/articles/dive-into-webgpu-part-1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://okaydev.co/articles/dive-into-webgpu-part-1</a><p data-notion-block-id=\\"1b8e548d-8a8e-8024-86ca-fd71dfad4f80\\">WebGPU\ub97c \uc0ac\uc6a9\ud558\ub294 \ud29c\ud1a0\ub9ac\uc5bc\uc785\ub2c8\ub2e4. \uac1c\ub150\uc5d0 \ub300\ud574\uc11c \uae4a\uac8c \uc124\uba85\ud558\uc9c4 \uc54a\uc9c0\ub9cc, \uba4b\uc9c4 \uc608\uc2dc 4\uac00\uc9c0\ub97c \ub9cc\ub4e4\uc5b4\ubcf4\uba74\uc11c WebGPU(<code>gpu-curtains</code> \ub77c\uc774\ube0c\ub7ec\ub9ac)\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc775\ud790 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b8e548d-8a8e-8014-997b-ddf426e32dce\\" id=\\"1b8e548d-8a8e-8014-997b-ddf426e32dce\\">Enzyme\uc5d0\uc11c RTL\ub85c</h2><a href=\\"https://open.nytimes.com/how-the-new-york-times-systematically-migrated-from-enzyme-into-react-testing-library-b3ea538d001c\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://open.nytimes.com/how-the-new-york-times-systematically-migrated-from-enzyme-into-react-testing-library-b3ea538d001c</a><p data-notion-block-id=\\"1b8e548d-8a8e-80f6-bfb2-e3cd9dbfe972\\">Enzyme\uc740 React hook\uc774 \ub4f1\uc7a5\ud558\uae30 \uc774\uc804\uc5d0 \uc88b\uc740 \ud14c\uc2a4\ud2b8 \uc720\ud2f8 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc600\uc9c0\ub9cc, React hook\uacfc React testing Library\uac00 \ub4f1\uc7a5\ud55c \uc774\ud6c4 \ud328\ub7ec\ub2e4\uc784\uc758 \ubcc0\ud654\uc640 \ud568\uaed8 \ub9ce\uc774 \ucc3e\uc9c0 \uc54a\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ubc29\uc2dd \uc18c\uac1c\uc640 \ud568\uaed8 \uc65c, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ubc29\uc2dd\uc744 \uc801\uc6a9\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b6e548d-8a8e-8052-8529-ddf601f308f6\\" id=\\"1b6e548d-8a8e-8052-8529-ddf601f308f6\\">\ucd5c\uc2e0 \ube0c\ub77c\uc6b0\uc800\ub97c \uc704\ud55c \ud301</h2><a href=\\"https://www.bram.us/2025/03/11/view-transitions-border-radius/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.bram.us/2025/03/11/view-transitions-border-radius/</a><p data-notion-block-id=\\"1bbe548d-8a8e-8027-9135-df61c4f2d81c\\">View Transition\uc744 \uc0ac\uc6a9\ud560 \ub54c border \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub354 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://harrisonbroadbent.com/blog/cool-native-html-elements/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://harrisonbroadbent.com/blog/cool-native-html-elements/</a><p data-notion-block-id=\\"1b8e548d-8a8e-80cf-b825-db0ed38710e2\\">\ucd5c\uc2e0 \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc801\uc6a9\ub41c \uc5ec\ub7ec HTML \ud0dc\uadf8\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://ishadeed.com/article/css-relative-colors/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/css-relative-colors/</a><p data-notion-block-id=\\"1b6e548d-8a8e-8006-a34b-fae39b3b17d9\\">hex\ub098 rgb \ud568\uc218\ub85c \uac10\uc2f8\uc838\uc788\ub294 \ubb38\uc790\uc5f4\ub85c \ub418\uc5b4\uc788\ub294 \uc0c9\uae54\uc744 \uc218\uc815\ud574\uc57c \ud560 \ub54c \uc27d\uac8c \uc218\uc815\ud560 \uc218 \uc788\ub294 \ud568\uc218\uc778 <code>color-function()</code>, <code>color-mix()</code>\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1b6e548d-8a8e-8054-8e8a-fd86f78a37cc\\" id=\\"1b6e548d-8a8e-8054-8e8a-fd86f78a37cc\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://blog.angular.dev/angular-19-2-is-now-available-673ec70aea12\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.angular.dev/angular-19-2-is-now-available-673ec70aea12</a><p data-notion-block-id=\\"1bbe548d-8a8e-80ea-9215-f747b164f373\\">Angular\uc5d0\uc11c \ud070 \uc5c5\ub370\uc774\ud2b8\ub294 \uc544\ub2c8\uc9c0\ub9cc, \ubc31\ud2f1 \uc5c6\uc774 \ud15c\ud50c\ub9bf \ubcf4\uac04 \uc791\uc131, \ube44\ub3d9\uae30 Signal\uc5d0 \ub300\ud55c \uc9c0\uc6d0 \uac15\ud654\ub294 \ub208\uc5ec\uaca8\ubcfc\ub9cc \ud558\ub124\uc694.</p><a href=\\"https://blog.vlt.sh/blog/reproducibility\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.vlt.sh/blog/reproducibility</a><p data-notion-block-id=\\"1bce548d-8a8e-80e6-b9a0-e9035ee1e9ed\\">\uacf5\uae09\ub9dd \uacf5\uaca9\uc744 \uc7ac\ud604\ud560 \uc218 \uc788\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4. npm \ud328\ud0a4\uc9c0 \uacf5\uae09\ub9dd \uacf5\uaca9\uc774 \ub9ce\uc774 \ubc1c\uc0dd\ud558\ub294 \uc9c0\uae08 \ud65c\uc6a9 \ubc29\ubc95\uc744 \uace0\ubbfc\ud574\ubd10\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1b8e548d-8a8e-8079-8493-ca86f621690b\\" id=\\"1b8e548d-8a8e-8079-8493-ca86f621690b\\">\ubc88\uc678: MCP\ub294 \ubb58\uae4c</h2><a href=\\"https://norahsakal.com/blog/mcp-vs-api-model-context-protocol-explained/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://norahsakal.com/blog/mcp-vs-api-model-context-protocol-explained/</a><p data-notion-block-id=\\"1b8e548d-8a8e-80ad-a53f-f1063f1cda7f\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 \ud070 \uc0c1\uad00\uc740 \uc5c7\uc9c0\ub9cc, AI\ub97c \uc0ac\uc6a9\ud558\ub294\ub370\uc5d0 \ub5a0\uc624\ub978 Model Context Protocal\uc774 \ubb54\uc9c0 \uc27d\uac8c \uc124\uba85\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. MCP \uac1c\ub150\uc774 \uc798 \uc774\ud574\ub418\uc5b4\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p>"}')}}]);